window.STORY_CHAPTERS["c5aa785bf73768125"]={"id":"c5aa785bf73768125","lines":[{"uid":"talk.vc.home_wait_leafa_tales_6#originalText","id":"talk.vc.home_wait_leafa_tales_6","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"希侬小姐的魔法……是叫星灵术吗？那个真厉害，能够确实把会飞的对象打下来喔。","en":"Shionne's magic...Astral Artes, was it? It's so amazing. She can blast flying foes out of the sky.","ja":"シオンさんの魔法……星霊術だっけあれ凄いね。空飛ぶ相手を的確に打ち落とせるんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_7#originalText","id":"talk.vc.home_wait_leafa_tales_7","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"一定要帮助他们两人回到原本的世界！就靠哥哥和我齐心合力！","en":"We just have to get those two back to their world! You and I have to do it together, Kirito!","ja":"絶対、あのふたりを元の世界に帰してあげようね!お兄ちゃんとあたしで!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_8#originalText","id":"talk.vc.home_wait_leafa_tales_8","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"就算我不小心被送到其他世界……只要和哥哥在一起，我想就没问题。","en":"If I were blasted away to another world...maybe I'd be okay as long as you were with me.","ja":"もしあたしが、別の世界に飛ばされちゃっても……お兄ちゃんと一緒だったら、大丈夫かも"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_tales_9#originalText","id":"talk.vc.home_wait_leafa_tales_9","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"哥哥，还好吗？毕竟平常不会穿成这样嘛。今天要不要休息一下？","en":"Are you okay? I know, you don't usually dress like that. Why don't we take a little break?","ja":"大丈夫、お兄ちゃん?普段、そんな格好してないもんね今日は少し休んだら?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_tales_1#originalText","id":"talk.vc.home_touch_leafa_tales_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嘿嘿，我好像是第一次戴这种发饰。怎么样？我戴起来好看吗？","en":"Hee-hee, I think this's the first time I've used a hair decoration like this. Well? Is it me?","ja":"えへへ、こういう髪飾りって初めてするかもどう、似合ってる?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_tales_2#originalText","id":"talk.vc.home_touch_leafa_tales_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"等、等一下！就算很稀奇，你突然这样摸我……我还是会吓到的。","en":"H-Hey! I know this is all exotic and new and stuff, but don't touch me like that...you startled me.","ja":"ちょ、ちょっと!珍しいからって、いきなり触られたら……ビックリしちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_tales_4#originalText","id":"talk.vc.home_touch_leafa_tales_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这服装很可爱吧！感觉就像魔法师。拿本魔法书在手上是不是更搭？","en":"What a cute outfit. It just screams “mage,\" doesn't it? Think I'd look good with a book of spells?","ja":"可愛い衣装だよね、これ魔法使いって感じで魔術書とか持ったら似合うかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_tales_5#originalText","id":"talk.vc.home_touch_leafa_tales_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我知道你很在意装备，但是不要摸这种地方啦……","en":"S-So I get that you're curious about my costume, but please don't touch me there...","ja":"そ、装備が気になるのはわかるけどそんなとこ、触らないでよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_tales_6#originalText","id":"talk.vc.home_touch_leafa_tales_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这套服装感觉好轻，好像能轻飘飘地飞上天！","en":"This costume is so light. I feel like I'm just gonna float away!","ja":"この衣装、なんだか軽くてふわふわ飛べちゃいそうだよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_tales_7#originalText","id":"talk.vc.home_touch_leafa_tales_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这是以蝴蝶为主题设计的吧……在这里，我很少看见这种装备，所以感觉很新鲜～！","en":"Yeah, it's a butterfly motif. This is so cool! I never see equipment like this here.","ja":"蝶々モチーフなんだよね……ここではこういう装備、あんまり見かけないから新鮮～!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_tales_1#originalText","id":"talk.vc.home_time_leafa_tales_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"早上醒来的瞬间感到很不可思议，忍不住想「我怎么会穿成这样」……","en":"When I woke up I was like, \"Why am I dressed like this...?\"","ja":"朝起きて、一瞬「なんでこんな格好してるんだっけ」って不思議に思っちゃった"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_tales_4#originalText","id":"talk.vc.home_time_leafa_tales_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"早安，哥哥。咦？你问我是谁……是我啊，莉法！真是的，只是穿了稍微不同的服装，竟然就认不出来……","en":"Good morning, Kirito. Uh...it's me. Leafa. Don't you recognize me?! Jeez. All I did was change clothes.","ja":"おはよう、お兄ちゃん。え、誰って……あたしだよ、リーファ! まったくちょっと違う衣装だからって……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_tales_7#originalText","id":"talk.vc.home_time_leafa_tales_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"欸，哥哥，哪边有餐点好吃的店家？我想带希侬小姐去。","en":"Hey, Kirito, where are the good restaurants here? I want to take Shionne out to eat.","ja":"ねえお兄ちゃん、ご飯の美味しいお店、どこかあるかなシオンさんを連れて行きたくて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_tales_10#originalText","id":"talk.vc.home_time_leafa_tales_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"因为到了这时间，我才敢说。这次活动只有哥哥跟我参加，感觉就像获得特别待遇一样，我好高兴。","en":"I know it's weird timing, but I'm glad I can share this event just with you. I feel really special.","ja":"こんな時間だから言うけど、今回のイベントはお兄ちゃんとふたりだけ特別扱いみたいで、うれしかったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_tales_1#originalText","id":"talk.vc.home_day_leafa_tales_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"希侬小姐问我为什么今天看起来很疲惫。如果跟她说「因为今天是星期一」，她会懂吗？","en":"Shionne asked me why I was so frazzled. Think she'd get it if I told her it was Monday?","ja":"シオンさんに、なんで今日は大変そうなんだって聞かれちゃった月曜日って説明して、わかるのかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_tales_2#originalText","id":"talk.vc.home_day_leafa_tales_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥，今天也一起努力寻找能让希侬小姐他们回去的方法吧。","en":"Another day, another fight to find a way to get Shionne and Alphen home! Let's get to it, Kirito.","ja":"今日もがんばって、シオンさんたちが帰る方法を見つけようねお兄ちゃん"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_tales_3#originalText","id":"talk.vc.home_day_leafa_tales_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"不知道希侬小姐他们的世界是否也有星期六和星期天？要是没有的话……会很辛苦吧。","en":"Do you think Shionne's world has weekends? What if they didn't...? Man, that would suck.","ja":"シオンさんたちのところにも土日ってあるのかななかったら……大変そう"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_tales_4#originalText","id":"talk.vc.home_day_leafa_tales_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"希侬小姐向我道谢说「谢谢妳今天带我四处游览」，能让她开心真是太好了。","en":"Shionne thanked me for showing her around today. I'm happy to help.","ja":"今日は案内してくれてありがとうってシオンさんがお礼言ってたよ喜んでもらえてよかったね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_tales_1#originalText","id":"talk.vc.home_season_leafa_tales_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天很温暖，好舒服喔。邀希侬小姐他们去野餐好了。","en":"It's so nice and warm today. Let's take Shionne and Alphen on a picnic.","ja":"今日は暖かくて気持ちいいねシオンさんたちも誘ってピクニックに行こうか"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_tales_2#originalText","id":"talk.vc.home_season_leafa_tales_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"这身装扮出乎意料地凉爽呢，或许满适合夏天的。","en":"Y'know, this outfit is much more breathable than I expected. Might be good for the summer.","ja":"この格好、案外涼しくて夏にはいいかも"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_tales_3#originalText","id":"talk.vc.home_season_leafa_tales_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"一听到我说秋天的食物很好吃，希侬小姐眼睛都亮了。看不出来，原来她是个爱吃鬼啊。","en":"When I told Shionne autumn has good food, she got so excited. Guess she's a closet foodie.","ja":"秋は食べ物が美味しいって言ったらシオンさんが喜んでたんだ見かけによらず食いしん坊なんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_tales_4#originalText","id":"talk.vc.home_season_leafa_tales_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"听说那边的世界里有个地方一整年都是寒冬。是不是就像北极一样呢？","en":"They say their world has an area that's winter all year round. Maybe it's like the North Pole?","ja":"向こうの世界には、一年中冬の地方があるんだって北極みたいな感じなのかな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_tales_1#originalText","id":"talk.vc.home_etc_leafa_tales_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"恭喜你完成使命！希侬小姐他们也有帮忙，得向人家好好道谢才行喔。","en":"Congrats on clearing the mission! We'd better thank Shionne and Alphen for helping out.","ja":"ミッションクリアおめでとう!手伝ってくれたシオンさんたちにもお礼言わないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_tales_2#originalText","id":"talk.vc.home_etc_leafa_tales_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"好像收到礼物了。欸，也让我看看嘛～没关系对吧？","en":"You've got a present. Will ya show it to me? C'mon, please?","ja":"プレゼントが届いているみたいね、あたしにも見せてよいいでしょ?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_tales_3#originalText","id":"talk.vc.home_etc_leafa_tales_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你看，下个使命已经更新啰。为了能帮上希侬小姐他们，你要早点确认喔。","en":"Hey, the next mission just came in. We'd better check it out, stat. Shionne and Alphen need our help.","ja":"ほら、次のミッションが更新されたよシオンさんたちのためにも早めに確認しておこうね"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_alo_swim_wait_1#originalText","id":"talk.vc.home_leafa_alo_swim_wait_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"如果我也练习的话，是不是就会游泳了呀……","en":"I wonder if I just practiced... I'd be able to swim, too?","ja":"あたしも練習したら泳げるようになるかなぁ……"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_alo_swim_touch_1#originalText","id":"talk.vc.home_leafa_alo_swim_touch_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我不会泳游，可别把我当笨蛋哦。","en":"I said I can't swim! So don't be making fun of me.","ja":"泳げないからって馬鹿にしないでね"},"kind":"dialogue"},{"uid":"talk.vc.home_leafa_alo_swim_touch_2#originalText","id":"talk.vc.home_leafa_alo_swim_touch_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"啊啊！等、等一下哥哥！住、注意一点啦……刚刚，碰到了……","en":"Ack! H-Hey Kirito! Careful there...that just hit me!","ja":"んあっ!ちょ、ちょっとお兄ちゃん!き、気をつけてよ……今、あたった"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_1st_1#originalText","id":"talk.vc.home_wait_leafa_1st_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"欸，偶尔跟我一起训练嘛。试试看，会很好玩的喔。","en":"Come on, let's practice together for a change! It'll be fun, I promise.","ja":"ねえ、たまには一緒に稽古やろうよやってみたら楽しいよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_1st_2#originalText","id":"talk.vc.home_wait_leafa_1st_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我也去考机车驾照好了……这样一来就能一起骑车了。","en":"Maybe I should get a motorcycle license, too. Then we could ride together!","ja":"あたしもバイクの免許取ろうかなあそうしたら、一緒に乗れるよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_1st_3#originalText","id":"talk.vc.home_wait_leafa_1st_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你老是勉强自己，很让人担心耶。拜托你多依赖我一点啦。","en":"You always overwork yourself and it seriously worries me. You should let me help out more.","ja":"君はいっつも無理してるからちょっと心配だよもっと、あたしを頼ってね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_1st_4#originalText","id":"talk.vc.home_wait_leafa_1st_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我还是觉得能够飞上天的世界最好玩了～","en":"I really do think I prefer a world where you can fly.","ja":"あたしはやっぱり、飛ぶことができる世界が楽しいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_1st_9#originalText","id":"talk.vc.home_wait_leafa_1st_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哈啰～你醒着吗？如果累了要好好休息喔。","en":"Hellooo? Are you awake? If you're tired, you should really let yourself rest.","ja":"もしもーし、起きてる?疲れちゃったならちゃんと休んでね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_1st_1#originalText","id":"talk.vc.home_touch_leafa_1st_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"真是的，动不动就把我当小孩子对待……我已经不是小孩子了啦。","en":"Jeez, why do you always have to treat me like that? I'm not a baby anymore, you know.","ja":"もう、すぐそうやって子ども扱いして……あたし、もう子どもじゃないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_1st_2#originalText","id":"talk.vc.home_touch_leafa_1st_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"现实世界中的我是短发，所以在VR世界里才会试着留长发。","en":"Since my hair's short IRL, I like having it long in VR.","ja":"リアルだと短いからVRの世界ではちょっと長い髪にしてみたんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_1st_4#originalText","id":"talk.vc.home_touch_leafa_1st_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呀！？你、你真是的……不可以这样啦……","en":"Eek! J-Jeez... Seriously. Can you stop doing that?","ja":"ひゃん!?も、もう……そういうのはダメだよ……?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_1st_5#originalText","id":"talk.vc.home_touch_leafa_1st_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"咦？有脏东西吗？……难道说根本没有脏东西，你却碰了我？","en":"Oh, is it dirty? Unless...you touched it even though it's not dirty?","ja":"あれ、汚れてた?……まさか、汚れてもないのに触ったの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_1st_6#originalText","id":"talk.vc.home_touch_leafa_1st_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"嗯，你叫我？我现在要去准备，等我一下喔。","en":"Hm, you called me? Sit tight, just gonna get ready.","ja":"ん、呼んだ?今準備するからちょっと待ってて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_1st_1#originalText","id":"talk.vc.home_time_leafa_1st_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"身体已经习惯晨练了，所以会不由自主地早起呢。","en":"I've gotten so used to morning practice that I always just wake up early.","ja":"朝練が習慣になっててどうしても早めに目が覚めちゃうんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_1st_4#originalText","id":"talk.vc.home_time_leafa_1st_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天的午餐要怎么解决？要不要偶尔一起吃午餐？","en":"What do you want to do for lunch today? Wanna eat together for a change?","ja":"今日のお昼はどうする?たまには一緒に食べようか?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_1st_7#originalText","id":"talk.vc.home_time_leafa_1st_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哇──星星好美喔！你看你看，有流星！","en":"Oooh, the stars are so pretty! Look! It's a shooting star!","ja":"うわー、星がきれい!見て見て、流れ星!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_1st_10#originalText","id":"talk.vc.home_time_leafa_1st_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"半夜醒来时，只要看见有你在……就令我很安心。","en":"Whenever I wake up in the middle of the night, I always feel safe...when I see you.","ja":"夜中、目が覚めて君がいると……安心するんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_1st_1#originalText","id":"talk.vc.home_day_leafa_1st_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"星期一会觉得郁闷，都是错在星期天过得太开心！","en":"Yeah, Mondays wouldn't be so hard on you if you didn't party so hard on Sundays!","ja":"月曜日が辛いのは日曜日が楽しすぎるのがいけないんだよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_1st_2#originalText","id":"talk.vc.home_day_leafa_1st_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"平日我有社团活动要忙……所以也常常没时间登录呢。","en":"I'm so busy with my after-school club that I can't log in much on weekdays.","ja":"平日は部活が忙しくて……なかなかログインできないことも多いんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_1st_3#originalText","id":"talk.vc.home_day_leafa_1st_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"假日到啦～你已经决定今天要做什么了吗？我还没有任何安排喔！","en":"Weee, finally a day off! Got any plans today? I'm totally free!","ja":"お休みだー今日の予定は決まってる?あたしは、何にもないよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_1st_4#originalText","id":"talk.vc.home_day_leafa_1st_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天也好开心呢。好好睡个觉之后，明天又得早起了。","en":"I had a lot of fun today. I'd better turn in early so I can wake up early again tomorrow.","ja":"今日も楽しかったねゆっくり寝て、明日はまた早く起きないと"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_1st_1#originalText","id":"talk.vc.home_season_leafa_1st_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"天气开始变暖后，在道场训练时总算比较不难受了。","en":"Now that it's warmer, training at the dojo has finally gotten a bit tough.","ja":"暖かくなって、やっと道場での稽古が辛くなくなってきたよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_1st_2#originalText","id":"talk.vc.home_season_leafa_1st_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"夏天要小心脱水。尤其玩游戏时，一定要记得补充水分！","en":"When it's summer you have to make sure to stay hydrated! Especially while you're gaming.","ja":"夏は脱水に気をつけないと特に、ゲーム中は忘れずに水分補給!"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_1st_3#originalText","id":"talk.vc.home_season_leafa_1st_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"秋天的烤地瓜好诱人……反正刚训练完，吃一点点就好……","en":"It's autumn, and the roasted sweet potatoes are calling to me... Maybe a li'l one as a treat after practice.","ja":"秋は焼き芋の誘惑が……トレーニングの後だから少しだけ……"},"kind":"dialogue"},{"uid":"talk.vc.home_season_leafa_1st_4#originalText","id":"talk.vc.home_season_leafa_1st_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天就煮火锅吧。大家一起吃，一定会从头暖到脚的！","en":"Let's have hot pot today. Nothing warms the soul quite like hot pot with good company!","ja":"今日はお鍋にしようかみんなで食べればきっと温まるよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_1#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_1","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"朔夜她动不动就要我带哥哥去风精灵领地，真是有够唠叨的。","en":"Whenever I try to talk to Sakuya, she cuts me off and insists I bring you to Sylph territory.","ja":"サクヤがさ、何かというとお兄ちゃんをシルフ領に連れてこいってうるさいんだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_2#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_2","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"我还满常跟其他人去冒险的喔。哥哥，你要不要偶尔也陪我们一起玩？","en":"I actually go adventuring with the others a lot. Wanna come play with us sometime?","ja":"あたしは結構ほかのみんなと冒険してるよ。お兄ちゃんも、たまにはあたしたちと一緒に遊んでみる?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_3#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_3","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"我好想看看哥哥在《SAO》里面的样子喔。虽然我也喜欢你现在的刺猬头啦。","en":"I sure wish I could've seen you in SAO... Though I do love your spiky hair here.","ja":"《SAO》にいたお兄ちゃんの姿も見てみたかったなあ今のツンツン髪も好きだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_4#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_4","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"像这样一块睡觉，感觉好像回到了从前一样。","en":"Whenever we sleep next to each other like this, I feel like we're little kids again.","ja":"こうして一緒に寝ているとなんだか昔に戻ったようなそんな気がするんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_5#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_5","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"我可以再靠过去一点吗？总觉得肩膀有点冷。","en":"Hey, can I scoot closer to you? My shoulders are kinda cold, you see...","ja":"ねえ、もう少しそっちに行ってもいい?なんだか、肩が寒くって"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_6#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_6","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"以前不同种族间很少组队，但现在越来越常见了。","en":"Parties with different fairy races used to be a pretty rare sight around here, but not anymore.","ja":"昔は異種族同士のパーティって珍しかったんだけど最近はそうでもなくなってきたの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_7#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_7","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"我也在这里买间自己的房子好了。买了之后，哥哥要常来玩喔。","en":"I think I'll buy myself a house in this world. And when I do, you're coming to visit, okay?","ja":"あたしも、こっちで自分の家を買ってみようかなあ。そうしたらお兄ちゃんもきっと遊びに来てね?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_8#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_8","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"……这股摸起来的触感，真的无法想像我们是在游戏里面。和现实的哥哥完全一样。","en":"This feels so...real. Like we're not inside a game. You feel just like my brother IRL.","ja":"……この手触り、やっぱりゲームの中とは思えないよね現実のお兄ちゃんと、同じだもん"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_alo_sleeping_9#originalText","id":"talk.vc.home_wait_leafa_alo_sleeping_9","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"想睡了吗？哥哥跟在现实世界一样贪睡耶。","en":"Are you sleepy? You always were a sleepyhead, even IRL.","ja":"眠くなっちゃった?寝ぼすけなところは、現実のお兄ちゃんと変わらないんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_1#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"金发也挺好看的吧？在现实中染金发需要一点勇气，但在这里就没问题。","en":"I rock the blond look, don't I? I'm not brave enough to dye it IRL, but I'm cool with it in-game.","ja":"金髪もなかなかいいでしょ?現実で染めるのはちょっと勇気がいるけど、ここなら平気"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_2#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"再来换我摸摸看。你的头发刺刺的，感觉让我有点上瘾了。","en":"Can I touch your hair now? I'm kind of really digging the spikes.","ja":"次はあたしに触らせてそのツンツンした髪の感じなんだか癖になっちゃったの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_3#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"呵呵，哥哥喜欢我的缎带吗？那你也戴戴看嘛，搞不好很适合你。","en":"Ooh, do you like my ribbon? Maybe you should wear it— I think you could pull it off.","ja":"ふふ、リボンが気になる? だったらお兄ちゃんもつけてみたら?案外似合うかも"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_4#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"在游戏里面，我希望身材比例看起来修长一点。毕竟我在现实是那个样子……","en":"I wish I could have a slimmer body in-game. I already have to deal with these curves IRL...","ja":"ゲームの中では、もっとスラッとしたプロポーションがよかったの現実でも、あんなだから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_5#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"虽说是在游戏里面，但这样不会太大胆了吗？既然你这样，那我也……","en":"Hey, I know we're in-game, but isn't that out of line? I mean, two can play at that game...","ja":"ゲームの中だからってちょっと大胆すぎない?だったら、あたしだって……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_6#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"在游戏里面，打扮的时候可以不去顾虑体型，这点真的很有趣。","en":"One thing I love about gaming is I can play with fashion without worrying about my body type.","ja":"ゲームだと、体型を気にせずファッションを選べるからそこはすっごく楽しいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_7#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"等一下……就算在游戏里面，被摸的时候还是有感觉的。真是的……","en":"Hey...I know we're in-game, but I can still feel you touching me. Jeez...","ja":"ちょっと……ゲームの中でも触られた感覚はあるんだからねもう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_leafa_alo_sleeping_8#originalText","id":"talk.vc.home_touch_leafa_alo_sleeping_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你再继续下去的话……我……真的会紧紧抱住哥哥不放手喔。","en":"If you take this any further... then...I really will grab you and never let go. Got it?","ja":"それ以上やったら……あたし……ホントにお兄ちゃんを捕まえて離さないからね?"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_1#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_1","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"这个世界现在是早上，另一边……应该还是傍晚吧？那么，再一下下就好……","en":"It's morning in this world, but IRL it's...evening, I think? So we can stay a bit longer...","ja":"こっちの世界は朝だね向こうは……まだ夕方かな?だったら、もうちょっとだけ……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_2#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_2","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"像这样盖着被子沐浴在早晨的阳光中，真的好幸福……","en":"I just love snuggling in bed as the morning rays caress me... It's just, pure bliss.","ja":"朝の光の中で、こうやってお布団に入ってるのはなんだか幸せだね……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_4#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_4","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"天色越来越亮了。你打算怎么做？也该起床了吧？","en":"Aw, it's gotten pretty bright out. What do you wanna do? Guess we'd better get up.","ja":"明るくなってきちゃったねどうする?さすがに起きようか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_5#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_5","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"今天有人会过来吗？没人的话……我就和哥哥一起赖床吧。","en":"Is anyone else coming today? If not...then maybe I'll just sleep in with you.","ja":"今日、誰か来るんだっけ?来ないなら……お兄ちゃんに合わせて寝坊しようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_7#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_7","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"这里好暗又好安静……不过有哥哥在身边，我完全不会害怕。","en":"It's so dark and quiet...but I have nothing to fear because you're here with me.","ja":"暗くて、静かで……でも、お兄ちゃんが側にいれば全然怖くないの"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_8#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_8","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"虽然时间早了点，要不要睡了？就算没办法马上睡着，聊着聊着就会想睡了。","en":"It's still a bit early, but wanna just turn in? We can always talk until we get sleepy.","ja":"少し早いけど、もう寝ちゃおうかすぐには眠れなくても話してればそのうち眠くなるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_10#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_10","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"我有点睡不着呢。哥哥，要不要一起在夜空中翱翔？和白天的感觉完全不一样喔。","en":"I just can't sleep... Hey, wanna go flying? The sky is a totally different beast at night.","ja":"なんか眠れないんだね、夜の空を一緒に飛ばない?昼間とは全然別の空だよ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_leafa_alo_sleeping_11#originalText","id":"talk.vc.home_time_leafa_alo_sleeping_11","speaker":{"cn":"莉法","ja":"リーファ"},"text":{"cn":"你还醒着吗？那……陪我聊一聊吧，像是聊聊小时候的事情。","en":"Are you still awake? Then...talk to me. We can talk about our childhood memories and stuff.","ja":"まだ起きてる?なら……少しお話ししようよ子どもの時の話とか"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_sleeping_1#originalText","id":"talk.vc.home_day_leafa_alo_sleeping_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"从星期一就泡在《ALO》里面，我不愧是哥哥的妹妹耶。","en":"Look at me, starting my week off with ALO... I guess I really am your little sister.","ja":"月曜日からこうやって《ALO》やってるあたしもやっぱりお兄ちゃんの妹なんだね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_sleeping_2#originalText","id":"talk.vc.home_day_leafa_alo_sleeping_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"要不要出门逛逛？就算是在游戏世界，老是睡觉也不太好吧？","en":"Wanna go out for a bit? It's a bit of a waste spending all our time in this world sleeping.","ja":"少しおでかけしようかいくらこっちの世界でも寝てばっかりはよくないよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_sleeping_3#originalText","id":"talk.vc.home_day_leafa_alo_sleeping_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"要不要整个假期都泡在游戏里面放松？我不介意喔。","en":"Wanna just chill here in this world during vacation? I'd be cool with that.","ja":"お休みの間、ずっとこっちの世界でゆっくりする?あたしは、それでもいいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_leafa_alo_sleeping_4#originalText","id":"talk.vc.home_day_leafa_alo_sleeping_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"星期日已经结束了，再怎么说都该回现实世界啦。虽然我很想继续留在这里。","en":"Well, Sunday's over—guess I'll head back to the real world. Though I'd rather stay here...","ja":"日曜も終わっちゃったしさすがにリアルに戻ろうかほんとは、もっとこうしてたいけど"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_1#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"新年快乐。希望今年能多多和哥哥在一起。","en":"Happy New Year! Looking forward to lots of quality time with you.","ja":"あけましておめでとう今年の一年は、お兄ちゃんとたくさん一緒にいられたらいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_2#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥的发型正适合扮鬼啊。看起来刺刺的嘛……呵呵。","en":"With that hairstyle, you make a perfect demon. Haha, it looks like demon horns.","ja":"お兄ちゃんのその髪型なら鬼の役にぴったりかもツンツンしてるし……ふふ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_3#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"能在情人节和哥哥独处，我好幸福……","en":"I get to spend Valentine's Day alone with you. I'm such a lucky girl...","ja":"バレンタインにお兄ちゃんとふたりきり、幸せだな……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_4#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_4","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"一到了女儿节，就会有点失落。因为接下来就快要换班或是毕业了。","en":"I always feel a bit glum when Hinamatsuri's close. It also means graduation and friends leaving.","ja":"お雛様の時期になると少し寂しくなるんだ。クラス替えとか、卒業とかが近くなるから"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_5#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"白色情人节会收到什么回礼呢～？呵呵呵，我很期待喔。","en":"I wonder what you're gonna get me for White Day? Teeheehee, I can't wait to see.","ja":"ホワイトデーは、どんなお返しをしてくれるのかなー?ふふふ、楽しみにしてるね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_6#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥说的谎从来不会伤害任何人，所以我其实有点期待你今年会说什么谎。","en":"Everyone always falls for your April Fool's pranks. So I'm actually looking forward to it.","ja":"お兄ちゃんの嘘は、誰も傷つけないだから、実はちょっと楽しみなんだ今年はどんな嘘なのかなって"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_7#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_7","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"虽然现实的我因为集训而离家很远，但在游戏内还是可以像这样在一起……我真的很庆幸自己有玩《ALO》。","en":"We're far apart IRL, but we get to be together when we game... I'm so glad I took up ALO.","ja":"現実では合宿で遠くにいるけどゲームの中でならこうやって……《ALO》やってて、よかったな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_8#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"连雨滴落在叶子上的声音都非常清楚。在现实中根本听不见这种声音，感觉好新鲜。","en":"In this world, I can even hear the sound of the rain hitting the leaves! It's so cool.","ja":"雨が葉っぱに当たる音がここまで聞こえる。現実だとこんな音は聞こえないから、なんか新鮮だね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_9#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"听说有在世界树上挂短签的活动。呵呵……感觉似乎很有趣。","en":"Did you hear? There's a Tanabata event where you tie wishes to The World Tree. Haha, sounds fun.","ja":"世界樹に短冊を飾るイベントがあるんだって。ふふ……なんだか面白そうだね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_10#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_10","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"小时候，我们不是一起在海边堆城堡吗？不知道在这个世界能不能这么玩。","en":"Remember how we used to build sand castles when we were little? Maybe we could build them here, too.","ja":"小さい頃、砂浜でお城を作って遊んだよねこの世界でも、作れるのかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_11#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"希望在暑假结束后，还有时间能像这样一起放松。","en":"I hope that we can spend some quality time together even after summer vacation is over.","ja":"夏休みが終わっちゃってもまたこうして、一緒にゆっくりする時間が作れるといいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_12#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"听说今天在《ALO》也能看到漂亮的月亮，到外头去看看吧。","en":"I hear you can get a good view of the moon in ALO, too. Let's go outside and check it out.","ja":"《ALO》でも、今日はきれいに月が見えるんだってちょっと、外に出てみようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_13#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_13","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"秋天有很多好吃的东西，所以万圣节的糖果得节制一点，不然会胖……","en":"Autumn has so much yummy stuff to eat! So I'm gonna go light on the candy...for my figure.","ja":"秋はおいしいものがいっぱいだから、ハロウィンのお菓子はほどほどにしないと、スタイルが……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_14#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_14","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"在《ALO》出现那座浮游城后，其实我有点担心。我怕你会想起以前那段难熬的时光。","en":"I was a little worried when that castle showed up in ALO. Thought it might trigger you...","ja":"《ALO》にあのお城ができた時実はちょっと心配だったんだ辛かったことを思い出すかもって"},"kind":"dialogue"},{"uid":"talk.vc.home_event_leafa_alo_sleeping_15#originalText","id":"talk.vc.home_event_leafa_alo_sleeping_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"我喜欢圣诞节的氛围。大家都沉浸在欢欣鼓舞的气氛中，看起来非常开心。","en":"I just love Christmas. Everyone's so happy and full of life.","ja":"クリスマスの雰囲気は好きみんながウキウキして楽しそうなんだもん"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_3#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥，生日快乐。等一下大家应该都会过来，但现在就让我先单独为你庆祝吧。","en":"Happy Birthday! The others should show up soon, but can I give you a present first?","ja":"お兄ちゃん、誕生日おめでとうそのうちみんな来ると思うけど今はあたしだけでお祝いさせて?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_5#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_5","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是爱丽丝小姐的生日，要是能在Underworld为她庆祝就好了。","en":"I wish we could celebrate Alice's birthday in Underworld.","ja":"アリスさんのお誕生日は本当ならアンダーワールドでやれるといいのにね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_6#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_6","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是亚丝娜小姐的生日，晚上预定在那间小木屋为她办庆生派对没错吧？","en":"We're throwing Asuna a birthday party tonight at your lodge, right?","ja":"アスナさんのお誕生日今日の夜、あのロッジでパーティーの予定だよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_8#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_8","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是诗乃小姐的生日。我觉得在《GGO》为她庆祝会比较好。","en":"It's Sinon's birthday today! We should probably throw her a party in GGO.","ja":"シノンさんのお誕生日《GGO》でお祝いするのがいいと思うな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_9#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_9","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"今天是有纪小姐的生日。希望她的剑术在现实世界也多少能让我参考一下。","en":"It's Yuuki's birthday today, huh. I'd love to watch her sword fight IRL sometime and take notes.","ja":"今日はユウキさんの誕生日だねユウキさんの剣術、現実でもちょっと参考にさせてほしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_11#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_11","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"罗妮耶小姐的生日你打算送什么呢？可别送太奇怪的东西喔。","en":"What're you getting Ronie for her birthday? No funny business, okay?","ja":"ロニエさんの誕生日は何を贈るつもりなの?変なものはダメだよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_12#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_12","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"缇洁小姐的头发那么漂亮，生日就送条搭配起来好看的缎带，你觉得怎样？","en":"I think a ribbon for Tiese's pretty hair would be just the thing for her birthday.","ja":"ティーゼさんの誕生日はあのきれいな髪に似合うリボンとか、いいかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_14#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_14","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"既然是莉兹的生日，送和冶炼有关的礼物比较好吧。","en":"I guess Liz would probably like blacksmithing tools for her birthday.","ja":"リズさんのお誕生日ならやっぱり鍛冶関係のプレゼントがいいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_leafa_alo_sleeping_15#originalText","id":"talk.vc.home_bd_leafa_alo_sleeping_15","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"比起自己收到礼物，西莉卡收到给毕娜的礼物想必更开心。就给毕娜送个缎带吧。","en":"Silica would rather we get Pina a gift. Maybe we should get Pina a ribbon?","ja":"シリカちゃんは、自分への贈り物よりピナの物を喜んでくれるんだピナのリボンにしようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_alo_sleeping_1#originalText","id":"talk.vc.home_etc_leafa_alo_sleeping_1","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"恭喜哥哥完成任务。这次的报酬是什么呢？能让我看看吗？","en":"Congrats on clearing the quest! So, what was your reward? Can I see it?","ja":"クエストクリア、おめでとう今回の報酬は何だったの?あたしにも見せてくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_alo_sleeping_2#originalText","id":"talk.vc.home_etc_leafa_alo_sleeping_2","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"哥哥，你放报酬的箱子没囤到爆满吧？要时常确认才行喔。","en":"Hey, I hope you aren't letting gifts pile up in the Reward Box. You need to check it daily.","ja":"お兄ちゃん、報酬ボックスいっぱいにしてないでしょうね?すぐチェックしないとダメだよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_leafa_alo_sleeping_3#originalText","id":"talk.vc.home_etc_leafa_alo_sleeping_3","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"你听说下次任务的内容了吗？感觉还满好玩的，我们一起去挑战吧。","en":"Did you hear about the next quest? It sounds like fun—so let's do it together!","ja":"次のクエスト、聞いた?ちょっと面白そうだから一緒にチャレンジしようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_os_1#originalText","id":"talk.vc.home_wait_lisbeth_os_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"因为在不同的店也可以储到点数喔？不储就浪费了！","en":"Don't you know that you can get points from a variety of shops? We gotta get them before we miss out!","ja":"だって、いろんな店でポイント貰えるのよ?やらなきゃ損でしょ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_os_2#originalText","id":"talk.vc.home_wait_lisbeth_os_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"这个真的很方便啊。最重要的是，可以跟结衣说话！","en":"This will certainly come in handy. Plus, we can talk to Yui!","ja":"たしかにコレ便利よねなんていってもユイちゃんとも喋れるし!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_os_3#originalText","id":"talk.vc.home_wait_lisbeth_os_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"什么～？就那么不擅长AR战斗吗？","en":"Whaaat is it? Are you really that bad at AR combat?","ja":"なーに?そんなにAR戦闘が苦手なの?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_os_4#originalText","id":"talk.vc.home_wait_lisbeth_os_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"好了！给YUNA展现一下我们身经百战的团队精神吧！","en":"Alright! Let's show Yuna what we're made of!","ja":"よーし! ユナちゃんの前であたしたちの年季の入ったパーティプレイを見せてやろう!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_alo_swim_1#originalText","id":"talk.vc.home_wait_lisbeth_alo_swim_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"呵呵。怎么样？还不错吧。","en":"Hmmm... What do you think? Not too shabby, right?","ja":"ふっふーんどお?けっこういけるでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_alo_swim_1#originalText","id":"talk.vc.home_touch_lisbeth_alo_swim_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喂～喂，别当我是小孩！","en":"Hey, HEY! Don't treat people like kids!","ja":"こーらこら人を子供扱いしないの!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_alo_swim_4#originalText","id":"talk.vc.home_touch_lisbeth_alo_swim_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"等、等一下……你吓到我了……","en":"C-Come on now... Don't scare me like that...","ja":"ちょ、ちょっと……びっくりしたじゃない……"},"kind":"dialogue"},{"uid":"talk.vc.home_lisbeth_alo_2022_new_year_wait_1#originalText","id":"talk.vc.home_lisbeth_alo_2022_new_year_wait_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"恭喜啊～！今年一整年也多多指教啰！ ","en":"Happy New Year! Let's make it a good one. ","ja":"おめでとー!今年も一年、よろしくね! "},"kind":"dialogue"},{"uid":"talk.vc.home_lisbeth_alo_2022_new_year_wait_2#originalText","id":"talk.vc.home_lisbeth_alo_2022_new_year_wait_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"要是因为是新年就太懒散的话，我可是会咬你的哦？嘎哦─！开玩笑的啦～","en":"If you're blaming your laziness on New Year's, I'll bite-cha! ...Just kidding!","ja":"正月だからってぐうたらしてたらあたしが噛みついちゃうわよ?がおー! ……なんてね"},"kind":"dialogue"},{"uid":"talk.vc.home_lisbeth_alo_2022_new_year_touch_1#originalText","id":"talk.vc.home_lisbeth_alo_2022_new_year_touch_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"听说要是现在摸我的头的话，就会带来好运气哦！来来来，你多摸一点呀～","en":"If you pet my head, you might get something great in return! Go on, pet my head!","ja":"今のあたしの頭を撫でたらものすんごいご利益があるかもほらほらっ、もっと撫でてみなさいよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_1st_1#originalText","id":"talk.vc.home_wait_lisbeth_1st_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"虽然我是相信你啦，但可别让周遭的人太担心啊。","en":"I trust you, but just try not to worry everyone else, okay?","ja":"あんたのことは信じてるけど周りにあんまり心配をかけるんじゃないわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_1st_2#originalText","id":"talk.vc.home_wait_lisbeth_1st_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"嗯～这个敲打金属的感觉和声音……果然最棒了！","en":"Mmm, the sound and feel of hitting this metal... Ahhh, it's the best feeling in the world!","ja":"うーん、この金属を叩く感触と音……やっぱり最高ね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_1st_3#originalText","id":"talk.vc.home_wait_lisbeth_1st_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"VR世界的道具也是带有心的……这可是你教我的。","en":"Even VR-world items have souls... I learned that from you.","ja":"VR世界のアイテムだって心が宿る……あんたはそれを教えてくれたの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_1st_4#originalText","id":"talk.vc.home_wait_lisbeth_1st_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你最近都没来我店里吧？偶尔来晃晃嘛。","en":"Haven't seen you around my smithy lately. You should visit sometime.","ja":"最近あたしの店に顔を出さないわよね?たまには来てよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_1st_9#originalText","id":"talk.vc.home_wait_lisbeth_1st_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"欸，你在看哪啊？脸转过来看看这边吧。","en":"Hey. What're you looking at? Eyes up here, pal.","ja":"ねえ、どこ見てるの?ちょっとこっちに向いてみてよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_1st_1#originalText","id":"talk.vc.home_touch_lisbeth_1st_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"为什么要摸头呢？难道是因为你希望被摸……之类的？","en":"Why are you patting my head? Is that your way of telling me you want your head patted, too?","ja":"どうして頭を撫でるの?もしかして、自分が撫でてほしい……とか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_1st_2#originalText","id":"talk.vc.home_touch_lisbeth_1st_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"乱翘的头发已经弄不好了，以前我也很憧憬一头滑顺秀发的说。","en":"I'll always have wild hair. Though I used to really envy girls with silky locks.","ja":"くせっ毛は直らないのよ昔は、サラサラの髪に憧れた時もあったけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_1st_4#originalText","id":"talk.vc.home_touch_lisbeth_1st_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我们也曾经像这样……感受彼此的体温对吧……","en":"I remember that one time... where we felt each other's warmth like this.","ja":"……いつかも、こうやってお互いの体温を感じ合ったことがあったよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_1st_5#originalText","id":"talk.vc.home_touch_lisbeth_1st_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"停！再这样下去可就违反规则了！我只是你的专属冶炼师啊！","en":"Stop! That's against the rules! I am but your exclusive blacksmith. Don't you forget that!","ja":"ストップ!それ以上はルール違反!あたしはあくまで専属鍛冶師!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_1st_6#originalText","id":"talk.vc.home_touch_lisbeth_1st_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"呀啊……！真是的，对你完全不能掉以轻心呢！","en":"Eek! Jeez... Can't turn my back on you for a second!","ja":"きゃっ……まったく、油断も隙もないんだから、あんたは!"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_1st_1#originalText","id":"talk.vc.home_time_lisbeth_1st_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"吃过早餐了吗？什么？还没？那就快去吃啊。","en":"Have you eaten yet? What? You haven't? You should go eat something.","ja":"朝ご飯は食べたの?え、食べてない?だったら食べてきなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_1st_4#originalText","id":"talk.vc.home_time_lisbeth_1st_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"刚好店里没事，来，武器给我看看，我帮你保养一下。","en":"You just caught me during some downtime. Let me do a little maintenance on your weapon.","ja":"ちょうどお店が暇だったのほら、武器見せてメンテナンスしてあげるから"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_1st_7#originalText","id":"talk.vc.home_time_lisbeth_1st_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"差不多该准备关门了……你好像很闲呢，那帮我把牌子拿下来。","en":"I need to close up shop soon. You look bored. Here, help me take down the sign.","ja":"そろそろ閉店作業しないと……あんた、暇そうねそれじゃ、看板下げてきて"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_1st_10#originalText","id":"talk.vc.home_time_lisbeth_1st_10","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"总觉得晚上比较有灵感呢，是因为比较安静吗？","en":"I always get some of my best ideas at night. Maybe the quiet air does me good?","ja":"夜って、なんだかアイディアが思いつくの静かな空気がいいのかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_1st_1#originalText","id":"talk.vc.home_day_lisbeth_1st_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"昨天休假过得很开心，所以今天又能继续努力了。","en":"Thanks to a fun day off, I'll have a nice productive workweek ahead.","ja":"昨日のお休みが楽しかったから今日からまた頑張れるわ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_1st_2#originalText","id":"talk.vc.home_day_lisbeth_1st_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"这周有点闲呢，是不是该去做点宣传之类的呢……？","en":"I don't have much to do this week. Perhaps I should do some advertising...","ja":"今週は、ちょっと暇なのなにか宣伝とかしないとダメかなあ……?"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_1st_3#originalText","id":"talk.vc.home_day_lisbeth_1st_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"反正你周末很闲吧？我有想要收集的材料，陪我去吧。","en":"You're free this weekend, right? Come excavating with me. There's this material I want.","ja":"週末、どうせ暇でしょ?ちょっと、採りにいきたい素材があるんだけど、付き合って"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_1st_4#originalText","id":"talk.vc.home_day_lisbeth_1st_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"虽然明天是星期一，但晚一点再睡好了……再稍微聊一下吧。","en":"Tomorrow's Monday, but I think I'll stay up just a bit longer... Come on, talk with me.","ja":"明日は月曜だけどもう少しだけ起きてよっか……少し話そうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_1st_1#originalText","id":"talk.vc.home_season_lisbeth_1st_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"春天果然就是要赏樱呢，来规划一下赏花的计划吧。","en":"I do love seeing the cherry blossoms in spring. Let's make a plan to go see them.","ja":"春はやっぱり桜を見たいわお花見の計画、ちょっと考えようよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_1st_2#originalText","id":"talk.vc.home_season_lisbeth_1st_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"要是在夏天的酷暑底下冶炼，感觉会晕倒。","en":"Blacksmithing on a hot summer day? Just the idea of it makes me faint.","ja":"夏の暑い日に、鍛冶をやると倒れそうになっちゃう"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_1st_3#originalText","id":"talk.vc.home_season_lisbeth_1st_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我跟西莉卡去吃了好吃的水果，你应该也会喜欢。","en":"Silica and I just ate some really yummy fruit. I'm sure you'd like it, too.","ja":"シリカと、おいしいフルーツ食べてきたんだあんたも、多分好きだと思うわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_season_lisbeth_1st_4#originalText","id":"talk.vc.home_season_lisbeth_1st_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"小时候，我会把冰柱拿来当剑玩，只不过手会冻僵就是了。","en":"I used to sword fight with icicles when I was a kid. Made my hands numb, though.","ja":"小さい頃は、つららでチャンバラとかしてたなあ手がかじかんじゃうけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_1#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_1","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"……你的眼神真下流，我不是那个意思，你少给我误会喔。","en":"Get that creepy look out of your eyes, pal. It's not what you think.","ja":"……目がいやらしいんだけどそういうんじゃないから勘違いしないでよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"床就是这么小，贴在一起我也很无奈啊！","en":"It's not my fault we have to snuggle up close! It's a tiny bed!","ja":"ベッドが狭いんだからくっついちゃうのはしょうがないでしょ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_3#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_3","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"让人想起那个时候的事呢。你还记得吧？在那个龙的巢穴里，我们牵着手……","en":"Reminds me of that night we fell into the dragon's pit. Remember? We held hands...","ja":"あの時のことを思い出しちゃうな覚えてるでしょ、あのドラゴンの巣の中で、手をつないで……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_4#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_4","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"你的身体真是温暖呢。待在你身边，不知怎么地身体也会暖起来。","en":"You are always so warm. You're like a living space heater.","ja":"あんたの体って、温かいねそばにいると、なんだか体がぽかぽかしてくるの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_5#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_5","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"这次不只是武器，连防具都要做，得好好测量身体的尺寸才行。","en":"I'm gonna make some armor as well as weapons this time, so I've gotta take your measurements.","ja":"今度は武器だけじゃなくて防具も作るから、ちゃんと体の採寸しないとね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_6#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_6","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"今天店里休息，所以像这样悠悠哉哉的也没关系。","en":"My shop is closed today. So it's cool if I just take it easy.","ja":"今日はお店がお休みなのだから、こうしてダラダラしてても大丈夫"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_7#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_7","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"就算离开了这里，我也依旧是你的专属冶炼师，别忘了这点喔。","en":"Even after we make it out of here, I'm still gonna be your personal blacksmith. Don't you forget that.","ja":"ここから出た後も、あたしはあんたの専属鍛冶師だからそれは、忘れないでね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_8#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_8","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"起初你把剑折断的时候，我还在想要怎么教训你……但现在都是美好的回忆了。","en":"The first time I broke a sword, I totally freaked out. But now, it's a happy memory.","ja":"最初に剣を折られた時はどうしてやろうかと思ったけど……今はそれもいい思い出"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_sao_sleeping_9#originalText","id":"talk.vc.home_wait_lisbeth_sao_sleeping_9","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"欸，等一下……受不了，这么快就睡着了，一点戒心都没有……真是的。","en":"Hey. Could you maybe not... Like, fall asleep so quickly and be so damn irresistibly cute?!","ja":"ねえ、ちょっと……もう、寝付くのが早いんだからこんなに無防備で……まったく"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_1#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"只要被你摸头我就会说不上话……跟那个时候一样。","en":"Whenever you pat my head, I can't talk straight... Just like that one time.","ja":"あんたに頭をなでられると何も言えなくなっちゃうの……あの時と、一緒だから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"对、对女生来说，头发可是非常重要的。除了你之外，我是不会让别人碰的。","en":"H-Hey! A girl's hair is her life! You get a pass, but...I'm not letting anyone else touch it.","ja":"お、女の子の髪の毛って大事なものなんだからねあんた以外には、触らせないんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_3#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"不、不可以！我的脸，现在应该烫得不得了！","en":"S-Stop it! My face is probably red as a tomato right now!","ja":"だ、ダメ!あたしの顔、いまたぶんすっごく熱くなってるから!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_4#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"等、等一下！这样不好吧！你问为什么，这是因为……反正不行就对了！","en":"D-Dude! Not cool! Why? What do you mean, why?! Anyway...just stop it!","ja":"ちょ、ちょっと! まずいでしょ!なんでって、それは……とにかくダメ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_5#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"就算是我，睡觉的时候也会穿这样啦。……很奇怪吗？","en":"Hey, even I dress like this when I go to bed. Does it look...weird?","ja":"あたしだって、寝る時くらいはこういう格好するわよ……変、かな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_6#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"喂、喂……你该不会是睡迷糊了？这……这样的话，就没辙了……","en":"H-Hey! Wait a minute... Are you half-asleep? F-Fine... Guess I'll let this one slide.","ja":"こ、こら……もしかして、寝ぼけてるの?な……なら、しょうがないけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_7#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"被你做了这种事，就算是我……也是会无法忍耐的。","en":"If you keep that up much longer, I just might... Well, girls have urges, too, you know.","ja":"こんなことされたらあたしだって……我慢ができなくなっちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_lisbeth_sao_sleeping_8#originalText","id":"talk.vc.home_touch_lisbeth_sao_sleeping_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我们在那个洞窟里，也像这样握着彼此的手对吧，我哪可能忘得了啊。","en":"Back at that cave, we held hands like this too, remember? Of course you remember, come on.","ja":"あの洞窟でもさ、こうやって手を合わせたよね忘れるわけないよ、絶対"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_1#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_1","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"要起床了吗？还是，你想要再贪睡一下？","en":"Getting up already? Come on, let's sleep a bit longer.","ja":"もう起きる?それとも、もう少しだけ寝坊していこっか"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"差不多该准备开店了……但这被窝的魔力实在是……","en":"I've gotta get up and set up the shop...but...this bed's magic is too powerful...","ja":"そろそろお店の準備をしないと……でも、このお布団の魔力が……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_4#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_4","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"这个时间手上没握锤子感觉怪不踏实的……我还是起床好了。","en":"I always feel restless this time of day unless I'm holding my hammer... Guess I'll get up.","ja":"この時間は、ハンマーを持ってないと落ち着かなくて……やっぱり起きることにしようかな"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_5#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_5","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"你会不会觉得有点饿？不排斥轻食的话我是可以做，你也要吃对吧？","en":"Aren't you getting hungry? I'm gonna make something light. You'll have a bite too, right?","ja":"ちょっとお腹が空いてこない?軽いものでいいなら作るけどあんたも食べるでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_7#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_7","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"今天也勤奋工作了一整天。你也辛苦了，人平安真的是再好不过了。","en":"Another hard day's work in the books. Good work! I'm really glad you got back safe.","ja":"今日もよく働いたわねあんたもお疲れ様ほんと、無事で何より"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_8#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_8","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"晚上像这样盖同一条棉被……感觉有点难为情呢……","en":"Lying in bed together with you like this... It feels kinda... awkward? I guess.","ja":"夜こうやって同じ布団に入ってると……なんだか照れくさいって言うか……"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_10#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_10","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"……你还没睡啊？我自己也还醒着就是了。","en":"Oh...can't sleep? Well, not like I can talk.","ja":"……まだ起きてたの?なんて、あたしもあんたのこと言えないけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_time_lisbeth_sao_sleeping_11#originalText","id":"talk.vc.home_time_lisbeth_sao_sleeping_11","speaker":{"cn":"莉兹贝特","ja":"リズベット"},"text":{"cn":"周围越是安静，就越有两人独处的感觉……这样我怎么睡得着啊。","en":"When it gets quiet like this, I'm reminded it really is just you and me and... No way can I sleep.","ja":"周りが静かだと、ふたりきりだって実感しちゃって……こんなの眠れるわけないよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_sao_sleeping_1#originalText","id":"talk.vc.home_day_lisbeth_sao_sleeping_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天得打起精神才行，要是从星期一就过得散漫，那这礼拜会提不起劲的。","en":"Better bring it today. You never want to slack off on Mondays— it ruins the whole week.","ja":"今日は気合い入れないと月曜からダラッとしてたら今週もたないわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_day_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我最近觉得冶炼变得比之前更有成就感了。……或许是托你的福。","en":"I've been so inspired by black- smithing lately. I think...I might have you to thank for that.","ja":"最近、今まで以上に鍛冶にやりがいを感じてきたの……あんたの、おかげかも"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_sao_sleeping_3#originalText","id":"talk.vc.home_day_lisbeth_sao_sleeping_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我原本觉得在游戏里，是不是周末无所谓，但生活松弛有度还是很重要的呢。","en":"I used to think weekends were meaningless in-game, but work-life balance really is important, huh?","ja":"ゲームの中だから土日も関係ないって思ってたけどメリハリって重要なんだよね"},"kind":"dialogue"},{"uid":"talk.vc.home_day_lisbeth_sao_sleeping_4#originalText","id":"talk.vc.home_day_lisbeth_sao_sleeping_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天跟你过得很愉快，随时都欢迎你再约我……知道吗？","en":"I had so much fun with you today. If you want to do that again, I'm always up for it.","ja":"今日はあんたと一緒で楽しかったまたいつでも……ね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_1#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"新年快乐！难得过年，要发红包给我，我也欢迎喔。","en":"Happy New Year! Since it's a special day, it's cool if you want to give me New Year's money!","ja":"あけましておめでとうせっかくだから、お年玉もらってあげてもいいわよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"节分到了，我想把头盔做成鬼的造型来卖。什么？你说会卖不出去？是吗……","en":"I thought I'd make a demon-shaped helmet for Setsubun, so... Huh? What do you mean, it won't sell?","ja":"節分だから、鬼をかたどったヘルメット造ろうと思うんだえ、売れないって? そうかな……"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_3#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"这是情人节礼物！包含对你平日照顾的感谢，还、还有我的……心意。","en":"This' just a little valentine for being good in a fight! And y-you know, because I...want to...","ja":"これ、バレンタインの!あんたには、世話になってるしあ、あたしの気持ちも……あるし"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_4#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"要是在这里摆出女儿节娃娃，然后跟你一起欣赏，那一定很好玩吧。","en":"It'd be fun if we could set up a Hina doll shrine in this world, huh.","ja":"ここでもお雛様を飾ってあんたとふたりで眺めたらきっと楽しいだろうな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_5#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"咦？白色情人节的回礼？不好意思啊……不过，能收到你送的礼物，我很高兴。","en":"What's this? A White Day present for me? Oh, thanks... That's really sweet of you!","ja":"え、ホワイトデーのお返し?悪いわね……でもあんたからもらえて、うれしい"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_6#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天就算你说我可爱，我也不会相信的。要讲的话，就挑别的日子吧。","en":"Call me pretty all you want. I won't believe a word of it today. Tell me tomorrow instead.","ja":"今日かわいいって言われても全く信じられないから言うなら、別の日に言ってよね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_7#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"黄金周正是大赚一笔的时候呢。大家都去出任务，装备也会随之耗损不是吗？","en":"Golden Week's a gold mine, isn't it? Everyone's gonna need new armor after their quests.","ja":"ゴールデンウィークは稼ぎ時なんだよね。みんなクエストに行って、武具が消耗するでしょ"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_8#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"虽然听得到雷声，但只要和你待在这里，我好像就不会那么害怕了。","en":"I can hear the thunder, but since you're with me...I just might not be that scared.","ja":"雷の音が聞こえるけどここであんたと一緒なら少しだけ怖くないかも"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_9#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今年我想是不用把心愿写下来了。因为现在这样，我就已经够幸福了。","en":"I guess it's okay if I don't make a wish this year. Since I'm content the way things are.","ja":"今年は、願い事書かなくてもいいかな。だって、今このままで十分幸せなんだもん"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_10#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_10","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"外头传来了祭典的声音。能在家里听到这样的声音，有种幸福的感觉呢。","en":"I can hear the festival noises. There's something really cozy about hearing them from indoors.","ja":"外からお祭りの音が聞こえるなんか、こういう音を家の中で聞くのって、幸せを感じるの"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_11#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_11","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"虽然还在上学的时候，每到暑假尾声都觉得很讨厌，但这种想法现在想来也让人怀念呢。","en":"I used to hate going back to school after summer vacation, but...now I kinda miss it.","ja":"夏休みの終わりって、学校に行ってた時はイヤだったけど今思うと、その気持ちも懐かしいな"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_12#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_12","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"好啦好啦，我有准备赏月的团子啦。你真的是……比起可人更爱美食呢。","en":"Here, a special dessert for the Moon Festival. Sheesh, is food the only thing on your mind?","ja":"はいはい、お月見団子はちゃんと用意してあるわよほんとあんたは、色気より食い気ね"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_13#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_13","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"差不多该准备发糖果了呢。《SAO》里好像也有年纪比较小的孩子。","en":"We'd better get the candy ready. Seems like even SAO has little kids who want to trick-or-treat.","ja":"そろそろ、お菓子を配る準備をしないとね。《SAO》の中にも小さい子はいるみたいだし"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_14#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_14","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天是让人难以忘却的日子，不过只要有你在身旁，我感觉自己也能存活下去。","en":"Today's a day that will haunt me forever. But you give me the strength to keep fighting.","ja":"今日は、忘れようにも忘れられない日でも、あんたがいてくれたらあたしも生き延びられる気がする"},"kind":"dialogue"},{"uid":"talk.vc.home_event_lisbeth_sao_sleeping_15#originalText","id":"talk.vc.home_event_lisbeth_sao_sleeping_15","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天这种节日，你确定要跟我一起过？你这样子，会让我有所期待的……","en":"Are you sure you're cool spending this special day with me? Way to get a girl's hopes up...","ja":"今日みたいな日に、あたしと一緒でいいの? そんなことされると少し期待しちゃう……"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_bd_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"要送我礼物？干嘛这么客气啦……不过，我很开心，我会好好爱惜的。","en":"A present for me? Oh, you shouldn't have... But thanks. I love it.","ja":"あたしにプレゼント?気を遣わなくてもいいのに……でも、うれしい。大切にする"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_sao_sleeping_3#originalText","id":"talk.vc.home_bd_lisbeth_sao_sleeping_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"生日快乐。能这样两人一起庆生，我也非常开心。","en":"Happy Birthday! I'm glad I get to celebrate it with you.","ja":"誕生日おめでとうこうやって、ふたりでお祝いできてあたしもうれしい"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_sao_sleeping_6#originalText","id":"talk.vc.home_bd_lisbeth_sao_sleeping_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"亚丝娜的生日你就别泡在这了，要好好为人家庆生喔。","en":"It's Asuna's birthday. So you shouldn't be here—go on, go celebrate it with her.","ja":"アスナの誕生日はここにいないで、ちゃんとお祝いしてあげてね"},"kind":"dialogue"},{"uid":"talk.vc.home_bd_lisbeth_sao_sleeping_15#originalText","id":"talk.vc.home_bd_lisbeth_sao_sleeping_15","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"今天是西莉卡的生日，大家一起来我店里大玩特玩一下吧！","en":"It's Silica's birthday. Let's all have a big bash at my shop!","ja":"シリカの誕生日だからうちのお店で、みんなでぱーっと騒ぎましょう!"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lisbeth_sao_sleeping_1#originalText","id":"talk.vc.home_etc_lisbeth_sao_sleeping_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"恭喜你完成任务。我想你肯定也累了，在这里好好休息吧。","en":"Congrats! You cleared the quest. You must be tired. Feel free to rest up here.","ja":"クエストクリア、おめでとう疲れたでしょうから、ここでゆっくり体を休めて"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lisbeth_sao_sleeping_2#originalText","id":"talk.vc.home_etc_lisbeth_sao_sleeping_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"好像有礼物送到了。说不定是重要的东西，我建议你早点确认比较好喔。","en":"I think you've got a present. You should check it ASAP. It might be important.","ja":"プレゼントが届いてるみたい大事な物かもしれないから早めに確認した方がいいわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_etc_lisbeth_sao_sleeping_3#originalText","id":"talk.vc.home_etc_lisbeth_sao_sleeping_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你要前往下一层吧？不晓得会碰上什么事，要先把装备都准备好喔。","en":"You're going to the next floor, right? Take plenty of equipment. Never know what you'll run into.","ja":"次の階層に進むんでしょう?何があるかわからないから装備はちゃんと揃えていってね"},"kind":"dialogue"},{"uid":"talk.vc.home_sachi_sao_christmas_wait_1#originalText","id":"talk.vc.home_sachi_sao_christmas_wait_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"圣诞快乐！","en":"Merry Christmas!","ja":"メリー・クリスマス!"},"kind":"dialogue"},{"uid":"talk.vc.home_sachi_sao_christmas_wait_2#originalText","id":"talk.vc.home_sachi_sao_christmas_wait_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"我想要找到……和你相遇的意义。","en":"I want to find the meaning... of our encounter...","ja":"君と出会った意味を……見つけたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_sachi_sao_christmas_wait_3#originalText","id":"talk.vc.home_sachi_sao_christmas_wait_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"如果可以的话，帮我一起装饰树好吗？上面太高了我手搆不到……","en":"Could you give me a hand with these Christmas tree decorations? My hand can't reach the top...","ja":"よかったら君も、ツリーの飾りつけ手伝ってくれる?上の方は手が届かなくって……"},"kind":"dialogue"},{"uid":"talk.vc.home_sachi_sao_christmas_touch_1#originalText","id":"talk.vc.home_sachi_sao_christmas_touch_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"这个兜帽……还装饰着熊的耳朵，是很可爱啦……就是有点令人害羞……","en":"This hoodie... with the bear ears... it's cute... but a little embarrassing... ","ja":"このフード……クマの耳がついてて可愛いんだけど、ちょっと恥ずかしいかも……"},"kind":"dialogue"},{"uid":"talk.vc.home_sachi_sao_christmas_touch_2#originalText","id":"talk.vc.home_sachi_sao_christmas_touch_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"你也穿穿看……？呵呵，你原本总是穿的整身黑，现在反而很显眼呢～","en":"How about trying it on...? Hehe... You're always wearing black, so this will stick out!","ja":"君も着てみる……?ふふ、いつも真っ黒だから目立っちゃうね"},"kind":"dialogue"},{"uid":"talk.vc.home_sachi_sao_christmas_touch_3#originalText","id":"talk.vc.home_sachi_sao_christmas_touch_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"呀啊！……平、平时有穿着胸甲是还好……今天没有所以……","en":"Eek! I-I'm used to always wearing a breastplate... So not having one today is...","ja":"きゃっ! ……い、いつもは胸当てがあるからいいけど……今日はないから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_os_1#originalText","id":"talk.vc.home_wait_silica_os_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"哼哼哼哼哼哼哼哼～哼～YUNA的歌真的很好听呢～♪","en":"Lalala-lala-lalalala♪ Isn't Yuna's song just so catchy!","ja":"ふふふふんふんふんふふんふ〜んユナの曲いいですよねぇ〜♪"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_os_2#originalText","id":"talk.vc.home_wait_silica_os_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"太好了！通过游戏！一起玩AR游戏吧！","en":"We did it! Game cleared! Let's go try out an AR game!","ja":"やったー! ゲームクリアー!一緒にARゲームで遊びましょうよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_os_3#originalText","id":"talk.vc.home_wait_silica_os_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"真是的～！！我不管莉兹了！反正我的歌声就是不够透澈。","en":"Ugh! Lisbeth doesn't understand! My song is not so opaque!","ja":"もぉ〜!! リズさんなんて知りませんっ!どぉせあたしの歌は透き通ってないですよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_os_4#originalText","id":"talk.vc.home_wait_silica_os_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"下次YUNA要开演唱会！我们一起去看吧？","en":"Next time, Yuna has a concert! Do you want to go together?","ja":"今度ユナのライブがあるんです!一緒に行きませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_silica_sao_christmas_wait_1#originalText","id":"talk.vc.home_silica_sao_christmas_wait_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"街上布置了一棵大树。晚上要不要一起去看看呢？","en":"There's a big decorated tree in the town. Would you like to go see it when it gets dark?","ja":"街に大きなツリーが飾ってあったんです夜に見に行きませんか?"},"kind":"dialogue"}]};
